use anyhow::Result;
use glam::{Mat4,Vec3,Quat};
use crate::{Prepared,log::{Log,root},gpu::Gpu,scene::{Scene,TABLE},hud::Hud};
pub fn camera(az:f32,elevation:f32,distance:f32)->(Vec3,Quat,Mat4){let a=az.to_radians();let e=elevation.to_radians();let target=Vec3::new(0.0,TABLE,0.0);let eye=target+Vec3::new(a.sin()*e.cos(),e.sin(),a.cos()*e.cos())*distance;let view=Mat4::look_at_rh(eye,target,Vec3::Y);let rotation=view.inverse().to_scale_rotation_translation().1;(eye,rotation,view)}
pub fn offscreen(log:&Log,prepared:Prepared)->Result<()>{let mut gpu=Gpu::new(log,None,0xb000)?;let mut scene=Scene::new(prepared.source,prepared.assets,&mut gpu)?;scene.hud_scale=0.45;scene.elapsed_seconds=12.0;let mut hud=Hud::new(&scene.assets.portraits)?;let(width,height)=(1600,1100);let(texture,target)=gpu.offscreen(width,height)?;let projection=Mat4::perspective_rh(42f32.to_radians(),width as f32/height as f32,0.01,40.0);let mut reports=Vec::new();
 for(tick,name,az,e)in[(1800,"t1800",0.0,42.0),(24600,"front",0.0,42.0),(24600,"left60",-60.0,42.0),(24600,"right60",60.0,42.0),(24600,"top",0.0,80.8),(40987,"end",0.0,42.0)]{scene.seek(tick as f64);let(head,q,view)=camera(az,e,3.7);for _ in 0..12{scene.update(&mut gpu,head,q,0.1)?;}gpu.update_hud(hud.render(&scene.hud_content()))?;gpu.render(&target,projection*view,scene.world(),true);gpu.check()?;let path=root().join(format!("_tmp/shots/native_viewer_{name}.png"));gpu.save_png(&texture,&path)?;let snapshot=scene.snapshot();reports.push(serde_json::json!({"name":name,"az":az,"elevation":e,"drawCalls":gpu.calls,"snapshot":snapshot}));log.line(format!("오프스크린 {name} tick={tick} units={} drawCalls={}",scene.visible,gpu.calls));}
 scene.seek(24600.0);let(head,q,_)=camera(0.0,42.0,3.7);for _ in 0..12{scene.update(&mut gpu,head,q,0.1)?;}gpu.update_hud(hud.render(&scene.hud_content()))?;for(sign,name)in[(-1.0,"left"),(1.0,"right")]{let eye=head+q*Vec3::new(sign*0.032,0.0,0.0);let view=Mat4::from_rotation_translation(q,eye).inverse();gpu.render(&target,projection*view,scene.world(),true);gpu.save_png(&texture,&root().join(format!("_tmp/shots/native_viewer_stereo_{name}.png")))?;}
 crate::visual_validation::run(&mut scene,&mut gpu,&mut hud,&texture,&target)?;crate::validation::run(log,&mut scene,&mut gpu,&texture,&target)?;let report=serde_json::json!({"검증":"오프스크린 생성","원본전용":!scene.assets.generated,"reports":reports,"stereo":"IPD0.064m · 같은 머리중심 인스턴스 변환 재사용","실기기":"뷰어 세션 미실행"});std::fs::write(root().join("_tmp/logs/native_viewer_offscreen.json"),serde_json::to_vec_pretty(&report)?)?;Ok(())}
